#include <SPI.h>
#include <MFRC522.h>
#include <Servo.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// RFID Access Control
// Unlocks a servo when a scanned card's UID matches an authorized list.

const int RST_PIN = 9;
const int SS_PIN = 10;
MFRC522 rfid(SS_PIN, RST_PIN);

const int SERVO_PIN = 6;
const int BUZZER_PIN = 7;
Servo lockServo;

LiquidCrystal_I2C lcd(0x27, 16, 2);

// Add your own cards' UIDs here after reading them once via Serial (see step 1
// of Troubleshooting) — this example has one placeholder authorized card.
byte authorizedUID[][4] = {
  {0xDE, 0xAD, 0xBE, 0xEF}
};
const int AUTHORIZED_COUNT = 1;

void setup() {
  Serial.begin(9600);
  SPI.begin();
  rfid.PCD_Init();

  lockServo.attach(SERVO_PIN);
  lockServo.write(0); // locked

  pinMode(BUZZER_PIN, OUTPUT);

  lcd.init();
  lcd.backlight();
  lcd.print("Scan your card");
}

void loop() {
  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) {
    return; // no new card this loop
  }

  Serial.print("UID: ");
  for (int i = 0; i < rfid.uid.size; i++) {
    Serial.print(rfid.uid.uidByte[i], HEX);
    Serial.print(" ");
  }
  Serial.println();

  if (isAuthorized(rfid.uid.uidByte, rfid.uid.size)) {
    grantAccess();
  } else {
    denyAccess();
  }

  rfid.PICC_HaltA();
}

bool isAuthorized(byte* scannedUID, byte size) {
  for (int i = 0; i < AUTHORIZED_COUNT; i++) {
    bool match = true;
    for (int j = 0; j < size; j++) {
      if (scannedUID[j] != authorizedUID[i][j]) {
        match = false;
        break;
      }
    }
    if (match) return true;
  }
  return false;
}

void grantAccess() {
  lcd.clear();
  lcd.print("Access granted");
  lockServo.write(90); // unlocked
  delay(3000);
  lockServo.write(0); // re-lock
  lcd.clear();
  lcd.print("Scan your card");
}

void denyAccess() {
  lcd.clear();
  lcd.print("Access denied");
  tone(BUZZER_PIN, 300, 500);
  delay(1500);
  lcd.clear();
  lcd.print("Scan your card");
}
